/**
 * Tipos públicos do componente `IncidentTimeline`.
 *
 * Um incidente é uma sequência ordenada de eventos: detecção, paging,
 * escalonamento, mitigação, resolução. A timeline lista esses eventos em ordem
 * cronológica com nó colorido por severidade, chip por tipo, autor opcional
 * e timestamp relativo + absoluto.
 */

/** Severidade de um evento individual. */
export type IncidentSeverity = "low" | "medium" | "high" | "critical"

/** Estado geral do incidente. */
export type IncidentStatus = "ongoing" | "mitigated" | "resolved"

/** Tipo do evento (categórico, mapeado para um chip). */
export type IncidentEventType =
  | "detect"
  | "page"
  | "escalate"
  | "note"
  | "deploy"
  | "mitigate"
  | "resolve"
  | "postmortem"
  | "rollback"

/** Autor humano que executou o evento. */
export type IncidentActor = {
  name: string
  avatar?: string
  role?: string
}

/** Evento individual da timeline. */
export type IncidentTimelineEvent = {
  /** Identificador estável do evento (usado como React key e em onEventClick). */
  id: string
  /** Timestamp ISO do evento. */
  t: string
  /** Tipo do evento (chip). */
  type: IncidentEventType
  /** Severidade do evento (cor do nó). */
  severity: IncidentSeverity
  /** Título curto do evento. */
  title: string
  /** Descrição opcional, exibida abaixo do título. */
  description?: string
  /** Autor humano que executou o evento. */
  actor?: IncidentActor
  /** Metadados livres (chave/valor) exibidos como pequenos badges. */
  meta?: Record<string, string | number | boolean>
}

/** Props públicas do componente. */
export type IncidentTimelineProps = Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> & {
  /** Lista de eventos exibidos na timeline, na ordem cronológica. */
  events: IncidentTimelineEvent[]
  /** Estado geral do incidente (cor do chip e do badge no header). */
  status: IncidentStatus
  /** Severidade global do incidente (cor do badge no header). */
  severity: IncidentSeverity
  /** Timestamp ISO de início do incidente (obrigatório). */
  startedAt: string
  /** Timestamp ISO de resolução (omitir enquanto ongoing/mitigated). */
  resolvedAt?: string
  /** Título curto do incidente exibido no header. */
  title?: string
  /**
   * Quando `true`, atualiza os tempos relativos a cada 30s via `setInterval`.
   * Cleanup correto via `useRef` + `useEffect` no unmount. Default: `false`.
   */
  live?: boolean
  /** Callback disparado ao clicar num evento. */
  onEventClick?: (event: IncidentTimelineEvent) => void
}

"use client";

import { useRef, useEffect, forwardRef, type HTMLAttributes } from "react";
import type { IconComponent } from "@/lib/icon-context";
import { motion, AnimatePresence } from "motion/react";
import { useDropdownFluid } from "@/components/ui/dropdown-fluid-context";
import { cn } from "@/lib/utils";
import { fontWeights } from "@/lib/font-weight";
import { shapeMap } from "@/lib/shape-context";

// MenuItem is only used inside DropdownFluid, which opts out of the global pill
// shape — see dropdown-fluid.tsx for the rationale.
const shape = shapeMap.rounded;

interface MenuItemFluidProps extends HTMLAttributes<HTMLDivElement> {
  /** Optional leading icon. When omitted, the row renders text-only with no
   *  reserved icon column. */
  icon?: IconComponent;
  label: string;
  index: number;
  checked?: boolean;
  onSelect?: () => void;
}

const MenuItemFluid = forwardRef<HTMLDivElement, MenuItemFluidProps>(
  ({ icon: Icon, label, index, checked, onSelect, className, ...props }, ref) => {
    const internalRef = useRef<HTMLDivElement>(null);
    const hasMounted = useRef(false);
    const { registerItem, activeIndex, checkedIndex } = useDropdownFluid();

    useEffect(() => {
      registerItem(index, internalRef.current);
      return () => registerItem(index, null);
    }, [index, registerItem]);

    useEffect(() => {
      hasMounted.current = true;
    }, []);

    const isActive = activeIndex === index;
    const skipAnimation = !hasMounted.current;

    return (
      <div
        ref={(node) => {
          (internalRef as React.MutableRefObject<HTMLDivElement | null>).current =
            node;
          if (typeof ref === "function") ref(node);
          else if (ref)
            (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }}
        data-proximity-index={index}
        data-slot="menu-item-fluid"
        tabIndex={index === (checkedIndex ?? 0) ? 0 : -1}
        role="menuitemradio"
        aria-checked={!!checked}
        aria-label={label}
        onClick={onSelect}
        onKeyDown={(e) => {
          if (e.key === " " || e.key === "Enter") {
            e.preventDefault();
            onSelect?.();
          }
        }}
        className={cn(
          "relative z-10 flex items-center gap-2 px-2 py-2 cursor-pointer outline-none",
          shape.item,
          className
        )}
        {...props}
      >
        {Icon && (
          <span className="inline-grid">
            <span className="col-start-1 row-start-1 invisible">
              <Icon size={16} strokeWidth={2} />
            </span>
            <Icon
              size={16}
              strokeWidth={isActive || checked ? 2 : 1.5}
              className={cn(
                "col-start-1 row-start-1 transition-[color,stroke-width] duration-80",
                isActive || checked ? "text-foreground" : "text-muted-foreground"
              )}
            />
          </span>
        )}
        <span className="inline-grid flex-1 text-[13px]">
          <span
            className="col-start-1 row-start-1 invisible"
            style={{ fontVariationSettings: fontWeights.semibold }}
            aria-hidden="true"
          >
            {label}
          </span>
          <span
            className={cn(
              "col-start-1 row-start-1 transition-[color,font-variation-settings] duration-80",
              isActive || checked ? "text-foreground" : "text-muted-foreground"
            )}
            style={{
              fontVariationSettings: checked
                ? fontWeights.semibold
                : fontWeights.normal,
            }}
          >
            {label}
          </span>
        </span>
        <AnimatePresence>
          {checked && (
            <motion.svg
              key="check"
              width={16}
              height={16}
