const exampleFetchBash = `#!/usr/bin/env bash
set -euo pipefail

# Faz o fetch com retry exponencial
fetch_with_retry() {
  local url="$1"
  local max=5
  local delay=1
  for i in $(seq 1 $max); do
    if curl -fsSL "$url"; then
      return 0
    fi
    sleep $delay
    delay=$((delay * 2))
  done
  echo "falhou após $max tentativas" >&2
  return 1
}

fetch_with_retry "https://api.example.com/health"`

