        title: "Escalado para SRE sênior",
        description: "On-call primário não respondeu em 5min",
        actor: "ana.souza",
      },
      {
        id: "ev-4",
        t: tIso(peakMin),
        type: "note" as const,
        title: "Pico de impacto confirmado",
        description: `${Math.round(choice.cpuAtPeak)}% CPU, ${Math.round(choice.memAtPeak)}% memória`,
      },
      {
        id: "ev-5",
        t: tIso(28),
